const assert = require('node:assert/strict')
const fs = require('node:fs')
const src = fs.readFileSync('lib/whatsappServer.ts', 'utf8')
const page = fs.readFileSync('app/whatsapp/page.tsx', 'utf8')
const direct = fs.readFileSync('app/api/integracoes/whatsapp/conversa-direta/route.ts','utf8')
const gateway = fs.readFileSync('supabase/functions/whatsapp-gateway/index.ts','utf8')
assert.match(src, /const conversasDeGrupo = permitidas\.filter/)
assert.match(src, /\.from\('atendimento_whatsapp_grupos'\)/)
assert.match(src, /\.eq\('empresa_id', usuario\.empresa_id\)/)
assert.match(src, /\.in\('whatsapp_canal_id', canais\)/)
assert.match(src, /\.in\('grupo_jid', jids\)/)
assert.match(src, /const chave = `\$\{item\.whatsapp_canal_id\}:\$\{item\.grupo_jid\}`/)
assert.match(src, /grupoNomes\.get\(`\$\{conversa\.whatsapp_canal_id\}:\$\{conversa\.whatsapp_chat_jid\}`\)/)
assert.match(src, /\.\.\.\(nomeRealGrupo \? \{ grupo_nome: nomeRealGrupo, contato_nome: nomeRealGrupo \} : \{\}\)/)
assert.match(src, /for \(const chave of divergentes\) grupoNomes\.delete\(chave\)/)
assert.match(page, /ativa\.grupo_nome \|\| ativa\.contato_nome/)
assert.match(page, /c\.grupo_nome \|\| c\.contato_nome/)
assert.match(direct, /listarConversasAtendimento\(usuario, \{ modo: 'monitoramento' \}\)/)
assert.match(gateway, /nomeGrupoOrcamento !== "orcamento \/ assistencia"\) return null/)
console.log('PASS: nome real por canal+JID na caixa, cabeçalho e link direto; tenant, ACL e grupo exclusivo preservados')
